"""STEP15: fact base_concept → UMLS CUI/SNOMED/HPO (MRCONSO exact, DDXPlus 미참조) + 품질감사 + FREEZE"""
import pandas as pd, re, json, hashlib, time, subprocess, collections
O = "exp/step15_disease_profile_pilot"
F = pd.read_csv(f"{O}/01_disease_profile_facts.csv", dtype=str).fillna("")
m = pd.read_parquet("data/umls/mrconso_eng.parquet"); m = m[(m.SUPPRESS == "N") & m.SAB.isin(["SNOMEDCT_US", "HPO", "MSH", "NCI", "MTH", "MEDCIN", "ICD10CM", "RXNORM"])]
TAG = re.compile(r"\s*\((finding|disorder|procedure|substance|situation|event|morphologic abnormality|qualifier value|body structure|observable entity|product|organism|&amp; nos|nos)\)\s*$", re.I)
def norm(s): s = TAG.sub("", s.lower().strip()).replace("'s", "s").replace("'", ""); s = re.sub(r"[^a-z0-9 ]+", " ", s); return re.sub(r"\s+", " ", s).strip()
m["n"] = m.STR.map(norm); by = m.groupby("n")["CUI"].agg(set).to_dict(); sabs = m.groupby("CUI")["SAB"].agg(set).to_dict()
sn = m[m.SAB == "SNOMEDCT_US"].groupby("CUI")["CODE"].agg(lambda s: ";".join(sorted(set(s))[:2])).to_dict(); hp = m[m.SAB == "HPO"].groupby("CUI")["CODE"].agg(lambda s: sorted(set(s))[0]).to_dict(); pref = m[m.ISPREF == "Y"].drop_duplicates("CUI").set_index("CUI")["STR"].to_dict()
ALIAS = {"Acute sinusitis": "Acute sinusitis", "Chronic sinusitis": "Chronic sinusitis", "Sinusitis symptoms": "Sinusitis", "Nasal congestion": "Nasal congestion", "Facial pain": "Facial pain", "Anosmia": "Anosmia", "Sore throat": "Sore throat", "Fatigue": "Fatigue", "Rhinorrhea": "Rhinorrhea", "Symptom worsening after improvement": "", "Symptom persistence": "", "Common cold": "Common cold", "Seasonal allergic rhinitis": "Seasonal allergic rhinitis", "Tobacco smoke exposure": "Exposure to tobacco smoke", "Nasal polyp": "Nasal polyp", "Immunosuppression": "Immunosuppression", "Cystic fibrosis": "Cystic fibrosis", "Day care attendance": "", "Viral vs bacterial rhinosinusitis": "", "Sinus tenderness": "Sinus tenderness", "Objective sinonasal inflammation": "", "Recurrent acute rhinosinusitis": "Recurrent sinusitis", "Asthma": "Asthma", "Bacteria or fungus": "", "Multiple sinus infections": "Recurrent sinusitis", "Hoarseness": "Hoarseness", "Cervical lymphadenopathy": "Cervical lymphadenopathy", "Viral infection": "Viral disease", "Upper respiratory tract infection": "Upper respiratory tract infection", "Voice overuse": "Vocal abuse", "Gastroesophageal reflux disease": "Gastroesophageal reflux disease", "Irritant exposure": "", "Allergy": "Allergic disorder", "Persistent hoarseness": "Hoarseness", "Airway obstruction": "Airway obstruction", "Odynophagia": "Odynophagia", "Myalgia": "Myalgia", "Cough": "Cough", "Conjunctivitis": "Conjunctivitis", "Group A Streptococcus": "Streptococcus pyogenes", "Systemic viral infection": "Viral disease", "Dyspnea/dysphagia/rash": "", "Chest pain": "Chest pain", "Pain radiation": "Radiating pain", "Angina pattern": "Angina pectoris", "Dyspnea": "Dyspnea", "Diabetes mellitus": "Diabetes mellitus", "Coronary heart disease": "Coronary heart disease", "Hypertension": "Hypertension", "Hypercholesterolemia": "Hypercholesterolemia", "Obesity": "Obesity", "Sedentary lifestyle": "Sedentary lifestyle", "Smoking": "Smoking", "Age and sex": "", "Coronary artery disease": "Coronary arteriosclerosis", "Angina severity": "", "Nitroglycerin": "Nitroglycerin", "Myocardial infarction": "Myocardial infarction", "Coronary artery disease risk factors": "", "Heart murmur or irregular heartbeat": "Heart murmur", "Cardiac troponin": "Troponin", "Acute retroviral syndrome": "Acute HIV infection", "Flu-like symptoms": "Influenza-like illness", "Fever": "Fever", "Chills": "Chills", "Rash": "Rash", "Night sweats": "Night sweats", "Lymphadenopathy": "Lymphadenopathy", "Oral ulcer": "Oral ulcer", "Asymptomatic": "", "HIV-1 RNA or p24 antigen": "", "Nonspecific symptoms": "", "Transmission risk": "", "Fish ingestion": "Fish", "Histamine": "Histamine", "Symptoms": "", "Allergic reaction": "Allergic reaction", "Flushing": "Flushing", "Abdominal cramps": "Abdominal cramps", "Headache": "Headache", "Pruritus": "Pruritus", "Palpitations": "Palpitations", "Blurred vision": "Blurred vision", "Nausea and vomiting": "Nausea and vomiting", "Wheezing": "Wheezing", "Peppery taste": "Taste altered", "Antihistamine": "Antihistamine", "Exacerbation": "", "Chronic obstructive lung disease": "Chronic obstructive lung disease", "Productive cough": "Productive cough", "Hemoptysis": "Hemoptysis", "Cyanosis": "Cyanosis", "Peripheral edema": "Peripheral edema", "Sleep disturbance": "Sleep disturbance", "Respiratory infection": "Respiratory tract infection", "Smoke or pollutant exposure": "Exposure to smoke", "Chronic dyspnea": "Dyspnea", "No improvement in 48 h": "", "Episode": "", "Anxiety": "Anxiety", "Chest tightness": "Chest tightness", "Dizziness": "Dizziness", "Tachycardia": "Tachycardia", "Neck pulsation": "", "Alcohol use": "Alcohol consumption", "Caffeine use": "Caffeine", "Stimulant drug use": "Stimulant", "Digoxin": "Digoxin", "Wolff-Parkinson-White syndrome": "Wolff-Parkinson-White pattern", "Electrocardiogram": "Electrocardiogram", "Heart rate between episodes": ""}
rows = []
for r in F.itertuples():
    q = ALIAS.get(r.base_concept, r.base_concept); cuis = sorted(by.get(norm(q), set())) if q else []
    cuis = sorted(cuis, key=lambda c: (-("SNOMEDCT_US" in sabs.get(c, set()) or "HPO" in sabs.get(c, set())), -len(sabs.get(c, set()))))
    c = cuis[0] if cuis else ""
    status = "NOT_APPLICABLE(attribute/definition-only fact)" if not q else ("EXACT" if c else "FAIL")
    rows.append({"fact_id": r.fact_id, "disease": r.disease, "fact_category": r.fact_category, "base_concept": r.base_concept, "lookup_term": q, "umls_cui": c, "umls_pref": pref.get(c, ""), "snomed": sn.get(c, ""), "hpo": hp.get(c, ""), "n_cui_candidates": len(cuis), "alt_cuis": ";".join(cuis[1:4]), "attribute_fields_kept": ";".join(k for k in ["location", "severity", "onset", "duration", "frequency", "progression", "trigger", "relieving_factor", "history_context", "family_context", "exposure_context", "medication_context"] if getattr(r, k)), "mapping_status": status, "review_needed": status != "EXACT" or len(cuis) > 1})
C = pd.DataFrame(rows); C.to_csv(f"{O}/02_disease_profile_concepts.csv", index=False)
print(C.mapping_status.value_counts().to_dict(), "multi-CUI", int((C.n_cui_candidates > 1).sum())); print(C[C.mapping_status == "FAIL"][["fact_id", "base_concept", "lookup_term"]].to_string())
# quality audit (DDXPlus 미참조)
aud = []
for d, g in F.groupby("disease"):
    cc = C[C.disease == d]
    aud.append({"disease": d, "n_sources": len({s for x in g.source_id for s in x.split(";")}), "n_facts": len(g), "n_symptom_sign_facts": int(g.fact_category.isin(["SYMPTOM", "SIGN", "ASSOCIATED", "PHYSICAL_EXAM"]).sum()), "n_temporal_facts": int(((g.onset != "") | (g.duration != "") | (g.progression != "") | (g.frequency != "")).sum()), "n_location_facts": int((g.location != "").sum()), "n_trigger_relief_facts": int(((g.trigger != "") | (g.relieving_factor != "")).sum()), "n_risk_history_exposure_facts": int(g.fact_category.isin(["RISK_FACTOR", "MEDICAL_HISTORY", "FAMILY_HISTORY", "EXPOSURE", "MEDICATION", "DEMOGRAPHIC"]).sum()), "n_distinguishing_facts": int(g.fact_category.isin(["DISTINGUISHING", "NEGATIVE_FINDING", "RED_FLAG"]).sum()), "n_negative_facts": int((g.positive_or_negative == "negative").sum()), "n_concept_linked": int((cc.mapping_status == "EXACT").sum()), "n_facts_without_source": int((g.source_id == "").sum()), "n_facts_with_quantified_frequency": int((g.frequency != "").sum()), "n_review_needed": int((g.review_needed == "True").sum())})
A = pd.DataFrame(aud); A.to_csv(f"{O}/03_profile_quality_audit.csv", index=False); print(A.to_string())
assert A.n_facts_without_source.sum() == 0
fr = {"timestamp": time.strftime("%Y-%m-%dT%H:%M:%S"), "git_commit": subprocess.run("git rev-parse HEAD", shell=True, capture_output=True, text=True).stdout.strip(), "input_source_list": sorted({s for x in F.source_id for s in x.split(";")}), "file_sha256": {f: hashlib.sha256(open(f"{O}/{f}", "rb").read()).hexdigest() for f in ["00_source_registry.csv", "01_disease_profile_facts.csv", "02_disease_profile_concepts.csv", "03_profile_quality_audit.csv"]}, "disease_count": int(F.disease.nunique()), "fact_count": len(F), "raw_sha256sums": "data/disease_profiles/raw/SHA256SUMS.txt", "note": "DDXPlus evidence/condition/train statistics were NOT opened during profile construction (facts built only from raw source texts). Freeze: no edits to 01-03 after this point; changes go to Step15_v2."}
json.dump(fr, open(f"{O}/PROFILE_FREEZE.json", "w"), indent=1); print(json.dumps(fr["file_sha256"], indent=1))
